public class SafeQueryTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("buildUnsafe plain value",
                  "SELECT * FROM users WHERE name = 'Ada'",
                  SafeQuery.buildUnsafe("users", "Ada"));
            check("buildUnsafe hostile value",
                  "SELECT * FROM users WHERE name = 'x' OR '1'='1'",
                  SafeQuery.buildUnsafe("users", "x' OR '1'='1"));
            check("buildParameterized",
                  "SELECT * FROM users WHERE name = ?",
                  SafeQuery.buildParameterized("users"));
            check("buildParameterized other table",
                  "SELECT * FROM staff WHERE name = ?",
                  SafeQuery.buildParameterized("staff"));
            check("looksInjectable on concatenated query",
                  true,
                  SafeQuery.looksInjectable(SafeQuery.buildUnsafe("users", "Ada")));
            check("looksInjectable on parameterized query",
                  false,
                  SafeQuery.looksInjectable(SafeQuery.buildParameterized("users")));
            check("looksInjectable single stray quote",
                  false,
                  SafeQuery.looksInjectable("SELECT * FROM users WHERE name = 'Ada"));
            check("looksInjectable null",
                  false,
                  SafeQuery.looksInjectable(null));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected a normal return but got " + e);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

