public class SafeQuery {

    public static String buildUnsafe(String table, String value) {
        return "SELECT * FROM " + table + " WHERE name = '" + value + "'";
    }

    public static String buildParameterized(String table) {
        return "SELECT * FROM " + table + " WHERE name = ?";
    }

    public static boolean looksInjectable(String sql) {
        if (sql == null) {
            return false;
        }
        int quotes = 0;
        for (int i = 0; i < sql.length(); i++) {
            if (sql.charAt(i) == '\'') {
                quotes++;
            }
        }
        return quotes >= 2;
    }
}
